277	const FireSmartReplySchema = z.object({
278	  conversationId: z.string().uuid(),
279	  action: z.discriminatedUnion('kind', [
280	    z.object({ kind: z.literal('send_template'), templateSlug: z.string().min(1) }),
281	    z.object({ kind: z.literal('open_calendar_reschedule'), bookingId: z.string().uuid() }),
282	    z.object({ kind: z.literal('share_portfolio') }),
283	    z.object({ kind: z.literal('offer_slots'), days: z.union([z.literal(1), z.literal(3), z.literal(7)]) }),
284	    z.object({ kind: z.literal('send_aftercare_pdf') }),
285	    z.object({ kind: z.literal('request_deposit') }),
286	  ]),
287	  clientId: z.string().uuid(),
288	  channel: z.enum(['sms', 'email']).default('sms'),
289	})
290	
291	export async function fireSmartReplyAction(
292	  input: z.infer<typeof FireSmartReplySchema>,
293	): Promise<ActionResult<{ commId?: string | undefined; navigateTo?: string | undefined }>> {
294	  const authUser = await getAuthenticatedUser()
295	  if (!authUser) return { ok: false, error: 'Unauthorized' }
296	
297	  const parsed = FireSmartReplySchema.safeParse(input)
298	  if (!parsed.success) {
299	    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Invalid input' }
300	  }
301	
302	  const { conversationId, action, clientId, channel } = parsed.data
303	  const { studioId } = authUser
304	
305	  try {
306	    // Navigation actions — return route for client-side navigation
307	    if (action.kind === 'open_calendar_reschedule') {
308	      return {
309	        ok: true,
310	        data: { navigateTo: `/calendar?rescheduleBooking=${action.bookingId}` },
311	      }
312	    }
313	
314	    // Slot-offer action — render placeholder from template
315	    if (action.kind === 'offer_slots') {
316	      const templates = await listMessageTemplates(studioId, { category: 'reschedule' })
317	      const tpl = templates[0]
318	      if (!tpl) {
319	        return { ok: false, error: 'Reschedule template not found. Add one in Settings → Messaging.' }
320	      }
321	      const result = await sendSmsToClient(
322	        { studioId, clientId, body: tpl.body },
323	        authUser.user.id,
324	      )
325	      if (!result.ok) return { ok: false, error: result.error }
326	      revalidateMessages()
327	      return { ok: true, data: { commId: result.commId } }
328	    }
329	
330	    // Template-based actions — map slug to send
331	    let templateSlug: string | null = null
332	
333	    if (action.kind === 'send_template') {
334	      templateSlug = action.templateSlug
335	    } else if (action.kind === 'send_aftercare_pdf') {
336	      templateSlug = 'aftercare-guide'
337	    } else if (action.kind === 'request_deposit') {
338	      templateSlug = 'deposit-request'
339	    } else if (action.kind === 'share_portfolio') {
340	      templateSlug = 'portfolio-share'
341	    }
342	
343	    if (!templateSlug) {
344	      return { ok: false, error: 'Unknown smart reply action' }
345	    }
346	
347	    const templates = await listMessageTemplates(studioId)
348	    const tpl = templates.find((t) => t.slug === templateSlug)
349	
350	    if (!tpl) {
351	      return { ok: false, error: `Template '${templateSlug}' not found. Check Settings → Messaging.` }
352	    }
353	
354	    let result: Awaited<ReturnType<typeof sendSmsToClient>>
355	
356	    if (channel === 'email') {
357	      result = await sendEmailToClient(
358	        { studioId, clientId, subject: tpl.name, body: tpl.body },
359	        authUser.user.id,
360	      )
361	    } else {
362	      result = await sendSmsToClient(
363	        { studioId, clientId, body: tpl.body },
364	        authUser.user.id,
365	      )
366	    }
367	
368	    if (!result.ok) return { ok: false, error: result.error }
369	
370	    revalidateMessages()
371	    return { ok: true, data: { commId: result.commId } }
372	  } catch (err) {
373	    logger.error({ err, conversationId }, 'fireSmartReplyAction: unexpected error')
374	    return { ok: false, error: 'Failed to send smart reply' }
375	  }
376	}
